use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let m = 200001
    let mut sieve = []
    let mut cnt = []
    let mut last = []
    let mut i = 0
    while i < m {
        sieve.push(true)
        cnt.push(0)
        last.push(0)
        i += 1
    }
    let mut p = 2
    while p * p < m {
        if sieve[p] {
            let mut j = p * p
            while j < m {
                sieve[j] = false
                j += p
            }
        }
        p += 1
    }
    let mut c = 0
    let mut l = 0
    let mut k = 2
    while k < m {
        if sieve[k] {
            c += 1
            l = k
        }
        cnt[k] = c
        last[k] = l
        k += 1
    }
    let mut first = true
    for line in text.lines() {
        if first {
            first = false
            continue
        }
        let t = line.trim()
        if t.len() == 0 {
            continue
        }
        let n: int = t.parse().unwrap_or(0)
        if n < 2 {
            println("0 none")
        } else {
            println("${cnt[n]} ${last[n]}")
        }
    }
}

